package net.civeira.phylax.feature.identity.consentpurpose.application.usecase.create;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurposeChangeSet;
import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurposeKeyOptions;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;

class ConsentPurposeCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the consent purpose input values are kept when converted to a change set and back")
  void test_consent_purpose_create_input_change_set_round_trip() {
    ConsentPurposeCreateInput input = ConsentPurposeCreateInput.builder().uid("one")
        .tenant(TenantReference.of("one")).key(ConsentPurposeKeyOptions.MARKETING).title("one")
        .description("one").required(true).activationDate(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).build();
    ConsentPurposeChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    ConsentPurposeCreateInput copy = ConsentPurposeCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getKey().isPresent(), "key must be assigned by the builder");
    Assertions.assertEquals(input.getKey(), copy.getKey(),
        "key must survive the change set round trip");
    Assertions.assertTrue(input.getTitle().isPresent(), "title must be assigned by the builder");
    Assertions.assertEquals(input.getTitle(), copy.getTitle(),
        "title must survive the change set round trip");
    Assertions.assertTrue(input.getDescription().isPresent(),
        "description must be assigned by the builder");
    Assertions.assertEquals(input.getDescription(), copy.getDescription(),
        "description must survive the change set round trip");
    Assertions.assertTrue(input.getRequired().isPresent(),
        "required must be assigned by the builder");
    Assertions.assertEquals(input.getRequired(), copy.getRequired(),
        "required must survive the change set round trip");
    Assertions.assertTrue(input.getActivationDate().isPresent(),
        "activationDate must be assigned by the builder");
    Assertions.assertEquals(input.getActivationDate(), copy.getActivationDate(),
        "activationDate must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the consent purpose input builder can generate a new identifier")
  void test_consent_purpose_create_input_new_uid() {
    ConsentPurposeCreateInput input = ConsentPurposeCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        ConsentPurposeCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the consent purpose input starts empty and the setters assign values")
  void test_consent_purpose_create_input_setters() {
    ConsentPurposeCreateInput empty = ConsentPurposeCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getKey().isEmpty(), "key must be empty by default");
    Assertions.assertSame(empty, empty.setKey(ConsentPurposeKeyOptions.MARKETING),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getKey().isPresent(), "key must be assigned by the setter");
    Assertions.assertTrue(empty.getTitle().isEmpty(), "title must be empty by default");
    Assertions.assertSame(empty, empty.setTitle("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTitle().isPresent(), "title must be assigned by the setter");
    Assertions.assertTrue(empty.getDescription().isEmpty(), "description must be empty by default");
    Assertions.assertSame(empty, empty.setDescription("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getDescription().isPresent(),
        "description must be assigned by the setter");
    Assertions.assertTrue(empty.getRequired().isEmpty(), "required must be empty by default");
    Assertions.assertSame(empty, empty.setRequired(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRequired().isPresent(),
        "required must be assigned by the setter");
    Assertions.assertTrue(empty.getActivationDate().isEmpty(),
        "activationDate must be empty by default");
    Assertions.assertSame(empty,
        empty.setActivationDate(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getActivationDate().isPresent(),
        "activationDate must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
